type Registry = { invoke(...args: unknown[]): Promise<unknown>; inspect(...args: unknown[]): Promise<unknown> };
import { callCapability } from "./zz-residual-helper.js";
// APO view handler.
export async function view(registry: Registry): Promise<unknown> {
  const { invoke } = registry;
  await invoke("apo.policy.apply", {});
  await registry.invoke.call(registry, "apo.policy.apply", {});
  await callCapability(registry, "apo.policy.apply");
  await (0, registry.invoke)("apo.policy.apply", {});
  await (registry.invoke<unknown>)("apo.policy.apply", {});
  return await Reflect.apply(registry.invoke, registry, ["apo.policy.apply", {}]);
}

